const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

/** The strip as an HTML string. `current` (a site id such as "studio") adds aria-current="page" to that link. */
export function stripHtml({ current } = {}) {
  const cur = (site) => (site === current ? ' aria-current="page"' : "");
  const h = strip.home;
  return `<nav class="dh-strip" aria-label="${esc(strip.ariaLabel)}">
  <a class="dh-strip-home" href="${esc(h.href)}" data-dh-site="${esc(h.site)}"${cur(h.site)}><svg class="dh-strip-mark" viewBox="0 0 100 100" width="18" height="18" aria-hidden="true" focusable="false"><path fill-rule="evenodd" d="${strip.markPath}"/></svg><span class="dh-strip-name">${esc(h.label)}</span></a>
  <ul class="dh-strip-links">
${strip.links.map((l) => `    <li><a href="${esc(l.href)}" data-dh-site="${esc(l.site)}"${cur(l.site)}>${esc(l.label)}</a></li>`).join("\n")}
  </ul>
  <p class="dh-strip-label">${esc(strip.label)}<span class="dh-strip-more">${esc(strip.labelMore)}</span></p>
</nav>`;
}

/** CSS selector list that matches the current site's link from data-dh-site on <html> or on the strip. */
export function currentSiteSelector() {
  return strip.links.flatMap((l) => [
    `:root[data-dh-site="${l.site}"] .dh-strip:not([data-dh-site]) .dh-strip-links a[data-dh-site="${l.site}"]`,
    `.dh-strip[data-dh-site="${l.site}"] .dh-strip-links a[data-dh-site="${l.site}"]`,
  ]).join(",\n");
}
